import React, { useState, useEffect } from "react";
import "./LandingPage.css.css";
import { 
  FaBook, FaHistory, FaUsers, FaLandmark, FaCalendarAlt, 
  FaChevronDown, FaChevronRight, FaFacebook, FaTwitter, FaLinkedin, FaInstagram, 
  FaMapMarkerAlt, FaPhone, FaEnvelope 
} from "react-icons/fa";

// Updated data for ORA
const researchAreas = [
  { 
    title: "Oromo History Research", 
    description: "Investigating and documenting Oromo historical events and heritage.",
    icon: <FaHistory />, color: "#6a1b9a"
  },
  { 
    title: "Socio-Economic Studies", 
    description: "Analyzing the economy, civil service, and society before and after Abyssinian expansion.",
    icon: <FaBook />, color: "#0277bd"
  },
  { 
    title: "Cultural Preservation", 
    description: "Preserving Oromo cultural practices, traditions, and knowledge for future generations.",
    icon: <FaUsers />, color: "#f57f17"
  },
  {
    title: "Community Empowerment", 
    description: "Producing knowledge to empower communities through awareness and education.",
    icon: <FaLandmark />, color: "#2e7d32"
  }
];

const news = [
  { title: "Research on Oromo Civil Service Structures", date: "2025-11-15", summary: "New insights into historical governance systems in Oromia." },
  { title: "Historical Documentation Initiative", date: "2025-11-20", summary: "Collecting oral histories and archival materials from across Oromia." },
  { title: "Oromo Economic History Studies", date: "2025-11-10", summary: "Analyzing economic trends and impacts of external expansion on Oromo society." }
];

const stats = [
  { value: "30+", label: "Research Projects" },
  { value: "100+", label: "Researchers" },
  { value: "500+", label: "Historical Documents Collected" },
  { value: "20+", label: "Community Workshops" }
];

function Landing() {
  const [activeSection, setActiveSection] = useState("home");
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
      const sections = ["home", "about", "research", "news", "contact"];
      const scrollPosition = window.scrollY + 100;
      for (const section of sections) {
        const element = document.getElementById(section);
        if (element) {
          const offsetTop = element.offsetTop;
          const offsetBottom = offsetTop + element.offsetHeight;
          if (scrollPosition >= offsetTop && scrollPosition < offsetBottom) {
            setActiveSection(section);
            break;
          }
        }
      }
    };
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const scrollToSection = (sectionId) => {
    const element = document.getElementById(sectionId);
    if (element) element.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <div className="landing-page">
      {/* Navigation Bar */}
      <nav className={`navbar ${scrolled ? "navbar-scrolled" : ""}`}>
        <div className="container">
          <div className="navbar-brand">
            <span className="logo-text">ORA</span>
            <span className="logo-subtext">Oromo Research Association</span>
          </div>
          <div className="nav-links">
            {["home","about","research","news","contact"].map((section) => (
              <button
                key={section}
                className={`nav-link ${activeSection === section ? "active" : ""}`}
                onClick={() => scrollToSection(section)}
              >
                {section.charAt(0).toUpperCase() + section.slice(1)}
              </button>
            ))}
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <section id="home" className="hero-section">
        <div className="hero-overlay">
          <div className="container hero-content">
            <div className="hero-text">
              <h1 className="hero-title">
                Preserving <span className="highlight">Oromo History</span> and Knowledge
              </h1>
              <p className="hero-subtitle">
                Conducting evidence-based research to document, analyze, and empower communities through Oromo history, economy, and cultural heritage.
              </p>
              <div className="hero-buttons">
                <button className="btn btn-primary" onClick={() => scrollToSection("research")}>
                  Explore Our Research <FaChevronRight />
                </button>
                <button className="btn btn-outline" onClick={() => scrollToSection("contact")}>
                  Get Involved
                </button>
              </div>
            </div>
            <div className="hero-stats">
              {stats.map((stat, idx) => (
                <div key={idx} className="stat-card">
                  <div className="stat-value">{stat.value}</div>
                  <div className="stat-label">{stat.label}</div>
                </div>
              ))}
            </div>
          </div>
          <button className="scroll-indicator" onClick={() => scrollToSection("about")}>
            <FaChevronDown />
          </button>
        </div>
      </section>

      {/* About Section */}
      <section id="about" className="section about-section">
        <div className="container">
          <div className="section-header">
            <h2 className="section-title">About ORA</h2>
            <p className="section-subtitle">
              Producing knowledge and challenging false narratives about Oromo history.
            </p>
          </div>
          <div className="about-content">
            <div className="about-text">
              <p>
                The Oromoo Research Association (ORA) is dedicated to evidence-based research that produces a counter-hegemonic discourse against false narratives denying Oromo history.
              </p>
              <p>
                Our studies focus on Oromo society, economy, civil service, and historical events before and after Abyssinian expansion, aiming to document, preserve, and empower Oromo communities through knowledge.
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* Research Areas */}
      <section id="research" className="section research-section">
        <div className="container">
          <div className="section-header">
            <h2 className="section-title">Our Research Focus</h2>
            <p className="section-subtitle">Exploring history, culture, and society</p>
          </div>
          <div className="research-grid">
            {researchAreas.map((area, idx) => (
              <div key={idx} className="research-card" style={{ "--card-color": area.color }}>
                <div className="research-icon" style={{ color: area.color }}>{area.icon}</div>
                <h3 className="research-title">{area.title}</h3>
                <p className="research-description">{area.description}</p>
                <button className="research-link">
                  Learn More <FaChevronRight />
                </button>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* News Section */}
      <section id="news" className="section news-section">
        <div className="container">
          <div className="section-header">
            <h2 className="section-title">Latest Updates</h2>
            <p className="section-subtitle">Stay informed about ORA activities and research</p>
          </div>
          <div className="news-grid">
            {news.map((item, idx) => (
              <div key={idx} className="news-card">
                <div className="news-date">
                  <FaCalendarAlt />
                  <span>{new Date(item.date).toLocaleDateString()}</span>
                </div>
                <h3 className="news-title">{item.title}</h3>
                <p className="news-summary">{item.summary}</p>
                <button className="news-read-more">
                  Read Full Story <FaChevronRight />
                </button>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Contact Section */}
      {/* ... keep your previous contact and footer code unchanged ... */}
    </div>
  );
}

export default Landing;
